var IntMode;
IntMode = '^GetSurveyChannel()^'.toUpperCase();
if (!'^GetSurveyName()^'.includes("[TEST]")) {
    if (IntMode == "CAWI") {
        //$(".cf-page__navigation.cf-navigation .cf-navigation-back").hide()
