	border: 2px solid var(--PrimaryColorDark);
	font-family: arial;
	font-weight: bold;
	letter-spacing: -0.5px;
	line-height: 21pt;
}

.SRC_navigation_save {
	float: right;
	background-color: var(--SecondaryColor);
	color: var(--PrimaryColorDark);
	border: 2px solid var(--PrimaryColorDark);
}

/**Check box radiobutton**/

.cf-checkbox,
.cf-radio {
	height: 25px;
	width: 25px;
	background-color: #ffffff;
	cursor: pointer;
	border: 1px solid var(--radiobtn_border_grey);
}

.cf-checkbox--selected {
	background-color: var(--radio_checkbox_selected);
}

.cf-checkbox--selected::before {
	content: "";
	display: block;
	position: relative;
	width: 36%;
	height: 60%;
	top: 11%;
	margin: 0 auto;
	border: 3px solid #ffffff;
	border-top-color: rgba(0, 0, 0, 0);
	border-left-color: rgba(0, 0, 0, 0);
	transform: rotate(45deg) skew(10deg);
	/*background-color: var(--radio_checkbox_selected);*/
}

.cf-radio--selected::before {
	/*background-color: #000000;*/
	background-color: var(--radio_checkbox_selected);
	transform: scale(0.7);
}

/**Other & inputs box**/

 .cf-text-box {
 	width: 30em;
 	max-width: 100%;
 	border-radius: 0px;
 	/*border: none;*/
 	/*border-bottom: 1px solid #D0D7DE;*/
	border: 1px solid var(--editbox_border_grey);
 	background-color: #ffffff;
	/*border: 1px solid var(--editbox_border_grey);*/
	/*background-color: #F5F7FA;*/
 	font-size: inherit;
 	text-overflow: ellipsis;
 	padding: 0 .5em;
 	padding-top: 1px;
 	line-height: 2em;
 	height: 2em;
 }

.cf-text-box:focus {
	background-color: #ffffff;
}
