//WG - convert UTC time to local Melbourne call centre time
function UTCToMelbourne(dateValue) {
    if (!dateValue) return '';
    return new Date(dateValue).toLocaleString(
        'en-AU', 
        {
            timeZone: 'Australia/Sydney',
            hour12: false
        }
    );
}


function isCati() {
    return GetSurveyChannel()=="Cati" || f('tmp_mode').any('2') || f('mode').any('2');
}

function readOut() {
    return isCati() ? "(READ OUT)" : "";
}
function probe2Frame() {
    return isCati() ? "(PROBE TO FRAME)" : "";
}

function textSub(txt) {
    const channel = isCati() ? "cati" : "online";

    const map = {
        readout: {
            cati: "(READ OUT)",
            online: ""
        },

        probetoframe: {
            cati: "(PROBE TO FRAME)",
            online: ""
        },

        probetoscale: {
            cati: "(PROBE TO SCALE)",
            online: ""
        },

        probetoframeasrequired: {
            cati: "(PROBE TO FRAME AS REQUIRED)",
            online: ""
        },

        interviewernote: {
            cati: "INTERVIEWER NOTE:",
            online: ""
        },

        ifnecessary: {
            cati: "IF NECESSARY:",
            online: ""
        },

        multipleresponse: {
            cati: "(MULTIPLE RESPONSE)",
            online: "<i>Please select all that apply</i>"
        },

        yesnolist: {
            cati: "I’ll read through a list, just let me know yes or no for each.",
            online: ""
        }
    };

    return map[txt]?.[channel] || "";
}
