function getAusDate () {
	const current_date = new Date();
	//var offSet = 11; //AEST
	var offSet = 10; //AEDT
	var offsetUTC = offSet * 60 * 60 * 1000;
	const ausDate = new Date(current_date.getTime() + offsetUTC);
	return ausDate;
}
function chkDate (cdate=7, cmonth=6, cyear=2026) {
	//check cutoff date (default 22 Sep 2026)
	const today = new Date(getAusDate());
	today.setHours(0, 0, 0, 0);
	const cutoff = new Date(cyear, cmonth-1, cdate); // month starts at 0 (Jan)
	return (today >= cutoff);
}
function getSCREEN_1Text() {

	const yearToday = new Date().getFullYear();

	//*(MODE=1 AND (TOPUP_SAMPLE=0 OR 1) AND COMPLETE_STATUS_W4=0 OR 1), ONLINE AND MAIN SAMPLE/W4 TOP UP SAMPLE WHO PARTICIPATED IN WAVE 4) 
	if (f('topup_sample').any('0','1') && f('COMPLETE_STATUS_W4').any('0','1')) {
		return `<p>Welcome to the GENERATION Survey ${yearToday}.</p>
		<p>This survey is being conducted by the Australian National University (ANU), Social Research Centre (SRC) and the Australian Council for Education Research (ACER) on behalf of the Department of Education (DoE).</p>
		<p>Following on from the last survey, we want to know what you’ve been doing since last year. Whether you’re at university or TAFE, undertaking an apprenticeship or traineeship, landed a job, taken a gap year, or chosen another path, we’re interested in your story.</p>
		<p>Your participation is very important so that State and Federal Governments can improve services for young people all across Australia.</p>
		<p>The survey should take <b>around 30 minutes</b> to complete. You will receive <b>a $30 electronic gift card</b> as a thank you for your time. Survey participation is voluntary.</p>
		<p>Further information about the survey can be found at ${asLink("https://generationsurvey.org.au/about/")}</p>
		<p>If you agree to take part in this survey, please click next to start.</p>
		<p>For more information, please call the Social Research Centre on 1800 122 789 or email ${asLink("generation@srcentre.com.au")}</p>
		<p>GENERATION has been approved by the ANU Human Research Ethics Committee protocol number: H/2026/0221.</p>`;
	}

	if (f('topup_sample').any('2') || (f('topup_sample').any('1') && !f('COMPLETE_STATUS_W4').toBoolean())){
		let ins1 = "";
