$('#PreferredTheme_content').css('padding-left','0px');
$('.cf-list__item').css('margin-bottom','unset');

function getTheme(theme, att) {
    const img_path = "https://surveys.srcentre.com.au/isa/PYAMLMFAKKOYIBEYNHKRJRBIMIEALXOH/GEN/";

    const themes = {
        base: {
            logoPath: img_path + "1385x213_Black.png",
            primaryCol: "#004dcf",
            secondaryCol: "#FFFFFF"
        },
        purple: {
            logoPath: img_path + "1385x213_Purple.png",
            primaryCol: "#8102FF",
            secondaryCol: "#CFE4A1"
        },
        yellow: {
            logoPath: img_path + "1385x213_Yellow.png",
            primaryCol: "#ffe60d",
            secondaryCol: "#076d84"
        },
        red: {
            logoPath: img_path + "1385x213_Red.png",
            primaryCol: "#BD3F00",
            secondaryCol: "#B3F6FF"
        },
        green: {
            logoPath: img_path + "1385x213_Green.png",
            primaryCol: "#558006",
            secondaryCol: "#FFD3B3"
        }
    };

    return themes[theme]?.[att];
}

const preferredThemeMap = {
    PreferredTheme_1: "purple",
    PreferredTheme_2: "yellow",
    PreferredTheme_3: "red",
    PreferredTheme_4: "green"
};

$('div[id*="PreferredTheme_"].cf-image-answer').on("click", function () {

    var selectedTheme = preferredThemeMap[this.id] || "base";

    if ($(this).find('[id$="_control"]').attr('aria-checked') === 'true') selectedTheme = "base";


    $('.cf-header__text').children('img')
        .attr('src', getTheme(selectedTheme, "logoPath"));

    $('.cf-navigation-next').css({
        'background-color': getTheme(selectedTheme, "primaryCol"),
        'border': '2px solid ' + getTheme(selectedTheme, "primaryCol"),
        'color': getTheme(selectedTheme, "secondaryCol")
    });

    $('.cf-navigation-back, .SRC_navigation_save').css({
        'background-color': getTheme(selectedTheme, "secondaryCol"),
        'border': '2px solid ' + getTheme(selectedTheme, "primaryCol"),
        'color': getTheme(selectedTheme, "primaryCol")
    });

    $('a').css({'color': getTheme(selectedTheme, selectedTheme != "yellow" ? "primaryCol" : "secondaryCol")});
    $('hr').css({'border-color': getTheme(selectedTheme, "primaryCol")});
});

Script.ScriptCode:
function getProjectSettings(name) {
  const projectSettings = {
    // This might not be the same as the src_job_id. 
    // If you need to dedupe across multiple separate Forsta surveys, you would set them
    // all to have the same value below
    DEDUPE_PROJECT_CODE: "SRC3533",
    // set as a single string, NO spaces
    //e.g. LinA, ORU, Octopus, Pureprofile, Lightspeed, Open (for open link), Client
    PANEL_NAME: "Client",
    // Set the country code for whehre the survey is running. Is used by RD to detect country mismatches and 
    // block respondents for entering the survey
    // NZ for New Zealand etc (Can only set to one single country)
    COUNTRY_CODE: "AU",
    // Controls whether the screen containing Research Defender is automatically submitted
    // once the API queries have completed or the timeout is reached, whichever happens first.
    //
    // Useful when Research Defender is placed on an intermediate screen and respondents
    // should continue automatically without clicking Next.
    AUTO_SUBMIT: false,
  };
  return projectSettings[name];
}

/*
  Uncomment the relevant config below, appropriate for the sample source being used for the project.
  Currently supported types are:
    - LinA
    - Client sample with/without incentives
    - Non-probability panel / MMM / Polaron
    - Commercial list sample with/without incentives
    - A-BS push-to-web
    - RDD SMS push-to-web
    - Open link / social media **WITHOUT** incentives
    - Open link / social media **WITH** incentives
*/

// - LinA
// - Client sample with/without incentives
function getRDConfig(name) {
  const configs = {
    FAIL_ON_API_ERROR: false,
    THREAT_POTENTIAL_THRESHOLD: false,
    DUPLICATE_SCORE_THRESHOLD: false,
    COUNTRY_MISMATCH_CHECK: false,
    ACTIVITY_FAIL_ON_API_ERROR: false,
    ACTIVITY_COUNT_THRESHOLD: false,
  };
  return configs[name];
}

