const qid = "^CurrentForm()^";
const q = Confirmit.page.getQuestion("^CurrentForm()^");
const states = [
    ["Australian Capital Territory", "ACT"],
    ["New South Wales", "NSW"],
    ["Northern Territory", "NT"],
    ["Queensland", "QLD"],
    ["South Australia", "SA"],
    ["Tasmania", "TAS"],
    ["Victoria", "VIC"],
    ["Western Australia", "WA"]
];

autocomplete_state(document.getElementById("^CurrentForm()^_1_other"), states);

function autocomplete_state(inp, arr) {

    inp.addEventListener("input", function () {

        const val = this.value;
        closeAllLists();

        if (!val) return;

        const container = document.createElement("DIV");
        container.id = this.id + "autocomplete-list";
        container.className = "autocomplete-items";
        container.setAttribute(
            "style",
            "position:absolute;border:1px solid #d4d4d4;border-bottom:none;border-top:none;z-index:9999;background-color:#fff;overflow-y:auto;box-shadow:0 4px 6px rgba(0,0,0,0.1);"
        );
        this.after(container);

        const upperVal = val.toUpperCase();

        arr.forEach(state => {

            if (state[0].toUpperCase().includes(upperVal) || state[1].toUpperCase().includes(upperVal)) {

                const item = document.createElement("DIV");
                item.setAttribute(
                    "style",
                    "padding:10px;cursor:pointer;background-color:#fff;border-bottom:1px solid #d4d4d4;"
                );

                item.innerHTML = `${state[1]} (${state[0]})`;

                item.addEventListener("mouseover", function () {
                    this.style.backgroundColor = "#eee";
                });

