function autoComplete(inp, arr) {
  if (!inp) {
    //console.log("Autocomplete input not found.");
    return;
  }

  let currentFocus;

  inp.addEventListener("input", function (e) {
    cleanData(false);

    let val = this.value;
    closeAllLists();

    if (!val) {
      return false;
    }

    currentFocus = -1;

    const listContainer = createListContainer(this);
    //Confirmit.page.getQuestion("TOPUP_SCREENER")._otherValues["1"];
    const state_1 = document.getElementById("TOPUP_SCREENER_1_other").value
    var filterArr = state_1
    ? arr.filter(row => row[2] === state_1)
    : arr;
    if (arr.length == 0) filterArr = arr;
    populateList(filterArr, val, listContainer);
  });

  inp.addEventListener("keydown", function (e) {
    let x = document.getElementById(this.id + "autocomplete-list");

    if (x) {
      x = x.getElementsByTagName("div");
    }

    if (e.keyCode == 40) {
      currentFocus++;
      addActive(x);
    } else if (e.keyCode == 38) {
      currentFocus--;
      addActive(x);
    } else if (e.keyCode == 13) {
      e.preventDefault();

      if (currentFocus > -1) {
        if (x) {
          x[currentFocus].click();
        }
      }
    }
  });

  function addActive(x) {
    if (!x) {
      return false;
    }

    removeActive(x);

    if (currentFocus >= x.length) {
      currentFocus = 0;
    }

    if (currentFocus < 0) {
      currentFocus = x.length - 1;
    }

    x[currentFocus].classList.add("autocomplete-active");

    const activeItems = document.getElementsByClassName("autocomplete-active");

    for (let i = 0; i < activeItems.length; i++) {
      activeItems[i].style.backgroundColor = "#eee";
    }
  }

  function removeActive(x) {
    for (let i = 0; i < x.length; i++) {
      x[i].classList.remove("autocomplete-active");
      x[i].style.backgroundColor = "#fff";
    }
  }

  function createListContainer(inputElement) {
    const container = document.createElement("DIV");

    container.setAttribute("id", inputElement.id + "autocomplete-list");
    container.setAttribute("class", "autocomplete-items");
    container.setAttribute(
      "style",
      "position: absolute; border: 1px solid #d4d4d4; border-bottom: none; border-top: none; z-index: 99; background-color: #fff; overflow-y: auto; box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);"
    );

    inputElement.after(container);

    return container;
  }

  function populateList(arr, val, container) {
    const startsWithMatches = [];
    const includesMatches = [];
    const upperVal = val.toUpperCase();

    arr = arr.slice().sort(function (a, b) {
      return String(a[IDX.name] || "").localeCompare(String(b[IDX.name] || ""), undefined, { sensitivity: "base" });
    });

    arr.forEach(function (item) {
      const label = String(item[IDX.name] || "").toUpperCase();

      if (label.startsWith(upperVal)) {
        startsWithMatches.push(item);
      } else if (label.includes(upperVal)) {
        includesMatches.push(item);
      }
    });

    startsWithMatches.concat(includesMatches)
      .slice(0, 10)
      .forEach(function (match) {
        container.appendChild(createListItem(match, val));
      });
  }

  function createListItem(data, val) {
    const item = document.createElement("DIV");

    item.setAttribute(
      "style",
      "padding: 10px; cursor: pointer; background-color: #fff; border-bottom: 1px solid #d4d4d4;"
    );

    const displayText = String(data[IDX.name] || "").toUpperCase();

    item.innerHTML = highlightMatch(displayText, val);

    item.innerHTML += `
      <input type="hidden"
        class="selection"
        name="${escapeHTMLchar(data[IDX.name])}_${escapeHTMLchar(data[IDX.state])}"
        value="${escapeHTMLchar(displayText)}">
    `;

    item._schoolData = data;

    item.addEventListener("mouseover", function () {
      item.style.backgroundColor = "#eee";
    });

    item.addEventListener("mouseout", function () {
      item.style.backgroundColor = "#fff";
    });

    item.addEventListener("click", function (e) {
      const selectedInput = this.getElementsByTagName("input")[0];
      const selectedData = this._schoolData;

      if (osCode) {
        document.getElementById(`${qid}${osCode}_other`).value = selectedInput.value;
        Confirmit.page.getQuestion(qid)._otherValues[osCode.replace("_","")] = selectedInput.value;
        Confirmit.page.getQuestion(qid).setValue([osCode.replace("_","")]);
      } else {
        setQuestionValue(qid, selectedInput.value);
      }

      SCHOOL_FIELDS.forEach(function (field) {
        const val = cleanValue(selectedData[field.idx]);
        const textElement = document.getElementById(`${field.qid}_text`);

        if (textElement) {
          textElement.value = val;
        }

        setQuestionValue(field.qid, val);
      });

      closeAllLists();
    });

    return item;
  }

  function highlightMatch(text, val) {
    const upperVal = val.toUpperCase();
    const index = text.indexOf(upperVal);

    if (index === -1) {
      return escapeHTMLchar(text);
    } else if (index === 0) {
      return `<strong>${escapeHTMLchar(text.substring(0, val.length))}</strong>${escapeHTMLchar(text.substring(val.length))}`;
    } else {
      return `${escapeHTMLchar(text.substring(0, index))}<strong>${escapeHTMLchar(text.substring(index, index + val.length))}</strong>${escapeHTMLchar(text.substring(index + val.length))}`;
    }
  }

  function closeAllLists(elmnt) {
    let x = document.getElementsByClassName("autocomplete-items");

    for (let i = 0; i < x.length; i++) {
      if (elmnt != x[i] && elmnt != inp) {
        x[i].parentNode.removeChild(x[i]);
      }
    }
  }

  function setQuestionValue(qId, val) {
    Confirmit.page.getQuestion(qId).setValue(val);
  }

  document.addEventListener("click", function (e) {
    closeAllLists(e.target);
  });
}

document.querySelectorAll('input[type="text"]').forEach(function (el) {
  el.setAttribute("autocomplete", "off");
});

document.querySelectorAll(
  `#${qid}_3, #${qid}_4, #${qid}_99`
).forEach(function (el) {
  el.addEventListener("click", function () {
    cleanData(true);
  });
});

function cleanData(saveResp = true) {

  if (saveResp && !tmpSchoolData[NAME]) {
    SCHOOL_FIELDS.forEach(function (field) {
      const textElement = document.getElementById(`${field.qid}_text`);
      tmpSchoolData[field.qid] = textElement ? textElement.value : "";
    });
  }

  SCHOOL_FIELDS.forEach(function (field) {
    const q = Confirmit.page.getQuestion(field.qid);
    const textElement = document.getElementById(`${field.qid}_text`);

    q.setValue("");

    if (textElement) {
      textElement.value = "";
    }
  });

  if (!saveResp) {
    tmpSchoolData = {};
  }
}

if (osCode) {
  document.getElementById(`${qid}${osCode}_other`).addEventListener("focus", function () {
    if (tmpSchoolData[NAME]) {
      SCHOOL_FIELDS.forEach(function (field) {
        const val = tmpSchoolData[field.qid] || "";
        const textElement = document.getElementById(`${field.qid}_text`);

        Confirmit.page.getQuestion(field.qid).setValue(val);

        if (textElement) {
          textElement.value = val;
        }
      });
    }
  });
}

function cleanValue(val) {
  return val == null ? "" : String(val);
}

function escapeHTMLchar(str) {
  return cleanValue(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

