Script.ScriptCode:
function ter3QuestionText() {
    const ter1 = f('TER1');
    const loop = f('TER_lp').get();
    const studyYear = f('STUDY_YEAR').get();

    const question = "<p>What is the type of course / degree at university or higher education institution?</p>";

    // One course
    if (ter1.any('1')) {
        return question;
    }

    // Multiple courses, first loop
    if (ter1.any('2', '3', '4') && loop === '1') {
        return "<p>We would like to ask some questions about the university courses / degrees you have studied in " +
            studyYear +
            ". <i>Please provide details of your current or most recent course / degree first, then your other courses / degrees.</i></p>" +
            question;
    }

    // Multiple courses, subsequent loops
    if (ter1.any('2', '3', '4')) {
        return "<p>Please think about another course / degree you've studied since the beginning of the year.</p>" +
            question;
    }

    return question;
}

function terMask() {
    if (!f('TER1').toBoolean() || f('TER1').any('5','98','99')) return;
    if (f('TER1').any('3', '4')) {
        return set('1', '2', '3');
    }
    return f('TER1').any('1')
        ? set('1')
        : set('1', '2');
}

