const acText = "^CurrentForm()^"; // autocomplete text
const osCode = ""; // other specify code, "" if none
const acText_LABEL = `${acText}${osCode}_LABEL`
const acText_CODE = `${acText}${osCode}_CODE`

const getArr = JSON.parse(`^courseList()^`);

//Assign AutoComplete to text question
if ("^!f('scrn_reader').any('1')^" == "True") autoComplete(document.getElementById(`${acText}${osCode}${osCode?'_other':'_input'}`), getArr);
if (osCode) {
  document.getElementById(`${acText}${osCode}_control`).parentElement.hidden = true;
  document.getElementById(`${acText}${osCode}_other`).parentElement.style.marginLeft = 0;
  document.getElementById(`${acText}_content`).style.paddingLeft = 0;
}
//if (IsInProductionModeJS()) { - DATA NOT USED
  document.getElementById(acText_LABEL).setAttribute("style", "display:none");
  document.getElementById(acText_CODE).setAttribute("style", "display:none");
