var tmp_code = null;
var tmp_label = null;
var tmp_flag = null;

function saveTempData() {
  tmp_code = document.getElementById(`${qid_CODE}_input`).value;
  tmp_label = document.getElementById(`${qid_LABEL}_input`).value;
  tmp_flag = getSelectedCode('INSTITUTION_FLAG');
}

function cleanData() {
  setQuestionValue(qid_CODE, null);
  setQuestionValue(qid_LABEL, null);
  setQuestionValue('INSTITUTION_FLAG', null);
}

function getSelectedCode(qid) {
  var selected = document.querySelector(
    '#' + qid + '_content [role="radio"][aria-checked="true"]'
  );

  if (!selected) {
    return null;
  }

  return selected.id
    .replace(qid + '_', '')
    .replace('_control', '');
}

function setQuestionValue(qId, val) {
  Confirmit.page.getQuestion(qId).setValue(val);
}

function escapeHTMLchar(str) {
    return str.replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
}

if (oth) {
  document.getElementById(`${qid}${oth}_other`).addEventListener('focus', function () {
    if (tmp_code) {
      Confirmit.page.getQuestion(qid_CODE).setValue(tmp_code);
    }

    if (tmp_label) {
      Confirmit.page.getQuestion(qid_LABEL).setValue(tmp_label);
    }

    if (tmp_flag) {
      Confirmit.page.getQuestion('INSTITUTION_FLAG').setValue(tmp_flag);
    }
  });
}

