Script.ScriptCode:
function voc4QuestionText() {
    const voc2 = f('VOC2_REV');
    const loop = f('VOC_lp').get();
    const studyYear = f('STUDY_YEAR').get();

    const question = "<p>What is the type of course, certificate, apprenticeship or traineeship?</p>";

    // One course
    if (voc2.any('1')) {
        return "<p>What is the type of TAFE or VET course, certificate, apprenticeship or traineeship?</p>";
    }

    // Multiple courses, first loop
    if (voc2.any('2', '3', '4') && loop === '1') {
        return "<p>We would like to ask some questions about the TAFE or VET courses, certificates, apprenticeships or traineeships you have done in " +
            studyYear +
            ". <i>Please provide details of your current or most recent course/certificate/apprenticeship/traineeship first, then any others.</i></p>" +
            question;
    }

    // Multiple courses, subsequent loops
    if (voc2.any('2', '3', '4')) {
        return "<p>Please think about another TAFE or VET course, certificate, apprenticeship or traineeship you've started since the beginning of the year.</p>" +
            question;
    }

    return question;
}

function vocMask() {
    if (!f('VOC2_REV').toBoolean() || f('VOC2_REV').any('5','98','99')) return;
    if (f('VOC2_REV').any('3', '4')) {
        return set('1', '2', '3');
    }
    return f('VOC2_REV').any('1')
        ? set('1')
        : set('1', '2');
}

