Script.ScriptCode:
function voc5yes () {
    // doing apprenticeship/traineeship
    var vocCodes = String(vocMask()).split(",");
    if (vocCodes.some(code => f('VOC5', code).any('1','2'))) return true;
    return false;
}

function isStudying(type) {
    if (!type || type=='TER') {
        var terCodes = String(terMask()).split(",");
        if (terCodes.some(code => f('TER9', code).any('1'))) return true;
    }

    if (!type || type=='VOC') {
        var vocCodes = String(vocMask()).split(",");
        if (vocCodes.some(code => f('VOC8', code).any('1'))) return true;
    }
    return false;
}

f('ANYTER9').set(isStudying('TER') ? '1' : null);
f('ANYVOC8').set(isStudying('VOC') ? '1' : null);

