            const $rowControl = $scope.find('#mobile_TE3_REV_1_' + code + ' .cf-grid-layout__row-control');

            const $dk = $scope.find('#mobile_TE3_REV_DK_' + code + '_control').closest('.cf-checkbox-answer');
            const $ref = $scope.find('#mobile_TE3_REV_REF_' + code + '_control').closest('.cf-checkbox-answer');

            $dk.detach().appendTo($rowControl);
            $ref.detach().appendTo($rowControl);

        });

    });
}
apply3dGridFormat();

(function () {

    const grid = Confirmit.page.getQuestion('TE3_REV');

    const num = grid._innerQuestions.find(q => q._id === 'TE3_REV_1');
    const dk = grid._innerQuestions.find(q => q._id === 'TE3_REV_DK');
    const ref = grid._innerQuestions.find(q => q._id === 'TE3_REV_REF');

    grid._answers.forEach(a => {

        const code = a._code;

        // Number entered -> clear DK and REF
        $(`input[id*="_TE3_REV_1_${code}"]`)
            .off(`input.te3rev.${code}`)
            .on(`input.te3rev.${code}`, function () {

                dk.setValue(code, null);
                ref.setValue(code, null);

            });

        // DK selected -> clear number and REF
        $(`div[id*="TE3_REV_DK_${code}"]`)
            .off(`click.te3rev.dk.${code}`)
            .on(`click.te3rev.dk.${code}`, function () {

                num.setValue(code, null);
                ref.setValue(code, null);

            });

        // REF selected -> clear number and DK
        $(`div[id*="TE3_REV_REF_${code}"]`)
            .off(`click.te3rev.ref.${code}`)
            .on(`click.te3rev.ref.${code}`, function () {

                num.setValue(code, null);
                dk.setValue(code, null);

            });

    });

})();

