        if (
            today.getMonth() < dob.getMonth() ||
            (today.getMonth() === dob.getMonth() &&
                today.getDate() < dob.getDate())
        ) {
            age--; // less 1 year if yet to have their birthday this year
        }

        const yearOfArrival = f('YOA1').toNumber();

        if (yearOfArrival > age) {
            showError("Years lived in Australia cannot exceed your age.");
