function getFinalDob() {
    var value = null;

    if (f('student_dob').toBoolean()) {
        value = f('student_dob').get();
    } else if (f('DOBAUTH').toBoolean()) {
        value = f('DOBAUTH').get();
    } else if (f('DLDOB').toBoolean()) {
        value = f('DLDOB').get();
    } else if (f('DOB').toBoolean()) {
        value = f('DOB').get();
    } 

    if (!value) return null;

    var dob = new Date(value);

    return isNaN(dob.getTime()) ? null : dob;
}
