/**API DOCUMENT CAN BE FOUND BELOW**/
//https://kleberwebsite.datatoolscloud.net.au/kleberbrowser/KleberMethodDescription.aspx?Method=DataTools.Security.GenerateTemporaryRequestKey


function getKleberToken() {
    //Request the tempory key
    const requestString =  "https://kleber.datatoolscloud.net.au/KleberWebService/DtKleberService.svc/ProcessQueryStringRequest?Method=DataTools.Security.GenerateTemporaryRequestKey&ExpirySeconds=600&RequestId=&RequestKey=redacted&DepartmentCode=1111";
    var response = Http.Post(requestString,"","");

    // Find the starting and ending points of the key
    const startTag = 'TemporaryRequestKey="';
    const startIndex = response.indexOf(startTag) + startTag.length;
    const endIndex = response.indexOf('"', startIndex);

    // Extract the key
    const temporaryRequestKey = response.substring(startIndex, endIndex);

    //var jsonresult=JSON.parse(response)
    f('Kleber_token').set(temporaryRequestKey)
}

function prepopForm() {
    var qid = "FORM";
    if (!f(`${qid}Asked`).any('1') && f('dob_error').any('0')){
        f(`${qid}Asked`).set('1');
        if (f('first_name').toBoolean()) f(`${qid}_1`).set(f('first_name'));
        if (f('last_name').toBoolean()) f(`${qid}_2`).set(f('last_name'));
        if (f('email').toBoolean()) {
            f('confirmApiEmail').set('1'); // don't validate from sample
            f(`${qid}_3`).set(f('email'));
        }
        if (f('sms_mobile').toBoolean() && f('sms_mobile').get().slice(0, 2) == '04') f(`${qid}_4`).set(f('sms_mobile').get().slice(0,10));
        if (f('student_hphone').toBoolean() && f('student_hphone').get().slice(0, 2) != '04') f(`${qid}_5`).set(f('student_hphone'));

        f('PAF_ADDRESS1').get()
	    f('PAF_LOCALITY').get()
	    f('PAF_State').get()
        f('PAF_POSTCODE').get()
        return "confirm";
    }
    return "provide";
}

function maskFormAdd() {
    var qset1 = new set();
    var qset2 = new set();
    if (
        f('DOB_ERROR').any('0') &&
        f('PAF_ADDRESS1').toBoolean() &&
        f('PAF_LOCALITY').toBoolean() &&
        f('PAF_State').toBoolean() &&
        f('PAF_POSTCODE').toBoolean()
    ) {
        qset1 = set('1','2');
    }
    if (!f('ADD_DET_FLAG').toBoolean() || f('ADD_DET_FLAG').any('0')) {
        qset2 = set('7','8');
    }
    return qset1.union(qset2);
}

