var homeNoField = f(qid + "_5");    // home number
var addressField = f(qid + "_6");    // address
// const AU_PHONE = /^\s*(?:(?:\+?61[\s\-.]?4[\s\-.]?(?:\d[\s\-.]?){8})|(0?4[\s\-.]?(?:\d[\s\-.]?){8})|(?:(?:\+?61[\s\-.]?[2378]|\(\s*0[2378]\s*\)|0[2378])[\s\-.]?\d{4}[\s\-.]?\d{4})|(13[\s\-.]?\d{2}[\s\-.]?\d{2})|(?:(?:1300|1800)[\s\-.]?\d{3}[\s\-.]?\d{3})|(190\d[\s\-.]?\d{3}[\s\-.]?\d{3}))\s*$/i;
const AU_MOBILE = /^\s*(?:\+?61[\s.-]?4(?:[\s.-]?\d){8}|0?4(?:[\s.-]?\d){8})\s*$/;
const AU_LANDLINE = /^\s*(?:(?:\+?61[\s.-]?[2378])|0[2378])[\s.-]?\d{4}[\s.-]?\d{4}\s*$/;
const NAME = /^[\p{L}L}'. -]*\.?$/u;

// #1 required fields provided
if (fnameField.toBoolean() && snameField.toBoolean() && emailField.toBoolean() && mobileField.toBoolean()) {
    // #2 validate name input
    if (!NAME.test(fnameField)) {
        showError("Please enter a valid first name using letters, spaces, apostrophes ('), and hyphens (-) only.")
    }
     // #3 validate email
    if (QuestionErrors() < 1 && emailField.toBoolean()) {
        if (!IsEmail(emailField)) {
            showError("Please provide a valid email address.");
        } else if ((emailField.toString().includes(".edu")) && !f('confirmSchoolEmail').any('1')) {
            // -- flag that user was notified so they can continue
            f('confirmSchoolEmail').set('1')
            showError("It looks like you may have entered a non-personal school email. Do you have a long term or personal email? If this is your long-term email, please click 'Next' to continue")
        } else {
            if (!f('confirmApiEmail').any('1')) {
                // -- flag that user was notified so they can continue
                f('confirmApiEmail').set('1');
                // Validity - Request the tempory key
                var APIKey = "redacted"
                var requestString =  "https://api.everest.validity.com/api/2.0/validation/addresses/";
                requestString = requestString + emailField
                var response = Http.Get(requestString,"",{"X-API-Key":APIKey});
                var jsonObj = JSON.parse(response);
                var resultReturn=JSON.parse(JSON.stringify(jsonObj["results"]))
                var resultCategory = JSON.stringify(resultReturn["category"])
                f('EmailReturnValues_category').set(resultCategory.toLowerCase().replace(/""/g, ""))
                f('EmailReturnText').set(JSON.stringify(resultReturn))

                var returnvalueCat=f('EmailReturnValues_category').get()
                if( returnvalueCat.includes("email_domain_invalid")) { 
                    showError("Domain for email (AFTER '@') does not exist, please double check it");
                } else if(returnvalueCat.includes("email_address_invalid")) {
                    showError("Email address does not exist, please double check your answer");
                } else if(returnvalueCat.includes("email_account_invalid")) {
                    showError("Email account does not exist, please double check your answer");
                } else if(returnvalueCat.includes("accept_all") || returnvalueCat.includes("role_address") || returnvalueCat.includes("disposable")) {
                    showError("Your email address is possibly invalid, please double check your answer. If this is your long term email address, please click 'Next' to continue");
                }
            }
        }
    }
    // #4 validate mobile number
    if (QuestionErrors() < 1 && mobileField.toBoolean()) {
        if (!AU_MOBILE.test(mobileField)) {
            showError("Please enter a valid mobile number")
        }
    }
} else {
    showError("Please provide your full name, an email and mobile number. It is important we have this information so we can re-contact you next year.");
}
// #5 validate surname
if (QuestionErrors() < 1 && snameField.toBoolean()) {
    if (!NAME.test(snameField)) {
        showError("Please enter a valid surname using letters, spaces, apostrophes ('), and hyphens (-) only.")
    }
}
// #6 validate home phone number
if (QuestionErrors() < 1 && homeNoField.toBoolean()) {
    if (!AU_LANDLINE.test(homeNoField)) {
        showError("Please enter a valid home phone number");
    }
}
if (QuestionErrors() < 1 && f('FORM_ADD').any('2')) {
    if (!addressField.toBoolean()) {
        showError("Please enter an updated address.")
    }
}
// -- reset flags if all conditions met
if (QuestionErrors() < 1) {
    f('confirmApiEmail').set(null);
    f('confirmSchoolEmail').set(null);
}

