function extractResultContent(xmlString) {
    let match = xmlString.match(/<Result(.*?)\/>/);
    return match ? String(match[1]).trim() : null; // Extract only the inner content
}

function convertStringToJson(dataString) {
    let jsonObject = {};
    let regex = /(\w+)="([^"]*)"/g; // Match key="value" with proper quotes
    let match;

    while ((match = regex.exec(dataString)) !== null) {
        jsonObject[match[1].trim()] = match[2].trim(); // Preserve spaces inside quoted values
    }

    return jsonObject;

}

function addDetMask() {
    if (f('add_det_flag').any('1')) return a('add_det');
    var qset1 = new set();
    var qset2 = new set();
    if (f('FORM_add').any('7')) {
        qset1 = set('1','2','3');
    }
    if (f('FORM_add').any('8')) {
        qset2 = set('4','5','6');
    }
    return qset1.union(qset2);
}

if (f('add_det_flag').any('1') && !f('addDetAsked').any('1') && f('dob_error').any('0')) {
