    if (!f('email_2').toBoolean() && f('email_3').toBoolean()){
        if (f('email_3').toBoolean()) f('add_det_1').set(f('email_3'));
        if (f('email_4').toBoolean()) f('add_det_2').set(f('email_4'));
        //if (f('email_5').toBoolean()) f('add_det_3').set(f('email_5'));
    } else {
        if (f('email_2').toBoolean()) f('add_det_1').set(f('email_2'));
        if (f('email_3').toBoolean()) f('add_det_2').set(f('email_3'));
        if (f('email_4').toBoolean()) f('add_det_3').set(f('email_4'));
