var qid = CurrentForm();
var errors = [];

// Only validate if they have not already acknowledged the warning
if (!f('confirmAddDetNA').any('1')) {

    if (f('add_det').toBoolean()) {

        // email check
        for (var i = 1; i <= 3; i++) {
            let email = qid + "_" + i.toString();

            if (f(email).toBoolean()) {
                if (!IsEmail(f(email))) {
                    errors.push(`Please provide a valid alternative email ${i.toString()}.`);
                } else {
                    checkAddDetEmail(f(email), i.toString());
                }
            }
        }

        function checkAddDetEmail(email, idx) {
            var APIKey = "redacted";
            var requestString = "https://api.everest.validity.com/api/2.0/validation/addresses/" + email;

            var response = Http.Get(requestString, "", { "X-API-Key": APIKey });
            var jsonObj = JSON.parse(response);
            var resultReturn = JSON.parse(JSON.stringify(jsonObj["results"]));
            var resultCategory = JSON.stringify(resultReturn["category"]);

            f('EmailReturnValues_category').set(resultCategory.toLowerCase().replace(/""/g, ""));
            f('EmailReturnText').set(JSON.stringify(resultReturn));

            var returnvalueCat = f('EmailReturnValues_category').get();

            if (
                returnvalueCat.includes("email_domain_invalid") ||
                returnvalueCat.includes("email_address_invalid") ||
                returnvalueCat.includes("email_account_invalid") ||
                returnvalueCat.includes("accept_all") ||
                returnvalueCat.includes("role_address") ||
                returnvalueCat.includes("disposable")
            ) {
                errors.push(`Email ${idx} does not exist, please double check your answer.`);
            }
        }

        // mobile phone check
        const AU_PHONE = /^\s*(?:(?:\+?61[\s\-.]?4[\s\-.]?(?:\d[\s\-.]?){8})|(0?4[\s\-.]?(?:\d[\s\-.]?){8})|(?:(?:\+?61[\s\-.]?[2378]|\(\s*0[2378]\s*\)|0[2378])[\s\-.]?\d{4}[\s\-.]?\d{4})|(13[\s\-.]?\d{2}[\s\-.]?\d{2})|(?:(?:1300|1800)[\s\-.]?\d{3}[\s\-.]?\d{3})|(190\d[\s\-.]?\d{3}[\s\-.]?\d{3}))\s*$/i;

        if (f(qid + "_4").toBoolean() && !AU_PHONE.test(f(qid + "_4"))) {
            errors.push("Please provide a valid alternative mobile number 1");
        }

        if (f(qid + "_5").toBoolean() && !AU_PHONE.test(f(qid + "_5"))) {
            errors.push("Please provide a valid alternative mobile number 2");
        }

        if (f(qid + "_6").toBoolean() && !AU_PHONE.test(f(qid + "_6"))) {
            errors.push("Please provide a valid alternative mobile number 3");
        }

    } else {
        errors.push("Please provide an alternative email and/or mobile, otherwise click Next.");
    }

    if (errors.length > 0) {
        f('confirmAddDetNA').set('1');

        showError(
            errors.join("<br/>") +
            "<br/>If all the details are correct, please click 'Next' to continue."
        );
    }
}
