Script.ScriptCode:
function GiftBeeSettings(keyStr) {
if (IsInProductionMode() && f('SurveyName').toBoolean() && f('SurveyName').toString().toUpperCase().startsWith('[LIVE]'.toUpperCase())) {

  // Production credentials
  var settings = {
     "authUrl": "https://api.giftbee.com/partner/oauth/token",
     "apiBaseUrl": "https://api.giftbee.com",
     "clientId": "redacted", 
     "clientSecret": "redacted", 
     "scope": "partner-rewards",
     "productUuid": "", // default product is GiftBee token
     "programUuid": "redacted", // GEN
     "redeemableCountry": "AU", 
     "fromName": "the Social Research Centre",
     "defaultCurrency": "AUD",
     "adminEmail": "wendy.guo@srcentre.com.au",
    "valueAmount": f('INCENTIVE_DOLLAR_VALUE').toBoolean() ? f('INCENTIVE_DOLLAR_VALUE').get() : "30", // the amount of incentive to award
     "smsFromNumber": "61420132531" // this from-number is FOR Research.
   };
  //settings.rewardSMSMessage = "Thanks for participating in the survey. Collect your $" + settings.valueAmount + " reward"; // shortlink will be appended to the end in script!
  settings.rewardSMSMessage = "Thank you for taking part in the National Survey of Community Satisfaction with Policing, a survey being conducted by the Social Research Centre. Here is a link to your $" + settings.valueAmount + " e-gift voucher as a small token of thanks. For more information call 1800 023 040."
}
else {
  // Staging environment / testing 
   var settings = {
    "authUrl": "https://api.giftbee.dev/partner/oauth/token",
    "apiBaseUrl": "https://api.giftbee.dev",
    "clientId": "redacted", // staging env only
    "clientSecret": "redacted", // staging env only
    "scope": "partner-rewards",
    "productUuid": "", // default product is a GiftBee token IF EMPTY
    "programUuid": "redacted", // default is to use the LinA float/program IF EMPTY
    "redeemableCountry": "AU",  
    "fromName": "the Social Research Centre",
    "defaultCurrency": "AUD",
    "adminEmail": "wendy.guo@srcentre.com.au",
     "valueAmount": f('INCENTIVE_DOLLAR_VALUE').toBoolean() ? f('INCENTIVE_DOLLAR_VALUE').get() : "30", // the amount of incentive to award
    "smsFromNumber": "61421261802" // this from-number is FOR TESTING ONLY, using here during testing. Use a different number in prod.
  }
  //settings.rewardSMSMessage = "Thanks for participating in the survey. Collect your $" + settings.valueAmount + " reward"; // shortlink will be appended to the end in script!
  settings.rewardSMSMessage = "Thank you for taking part in the National Survey of Community Satisfaction with Policing, a survey being conducted by the Social Research Centre. Here is a link to your $" + settings.valueAmount + " e-gift voucher as a small token of thanks. For more information call 1800 023 040."
}

  if (typeof settings[keyStr] !== "undefined") {
    return settings[keyStr];
  } else {
    return "";
  }

}

function GiftBeeGetAccessToken() {

  var url = GiftBeeSettings("authUrl");
  var data = {
    "grant_type": "client_credentials",
    "client_id": GiftBeeSettings("clientId"),
    "client_secret": GiftBeeSettings("clientSecret"),
    "scope": GiftBeeSettings("scope")
  };
  var headers = {
    "Accept": "application/json",
    "Content-Type": "application/json"
  };

  var result = Http.PostJson(url, data, headers);
  var jsonresult = JSON.parse(result);
  var access_token = jsonresult.access_token
  if (typeof access_token !== "undefined" && access_token != null && access_token != "") {
    return access_token;
  } else {
    var emailMsg = "GiftBee Auth Failed. Response: " + result;
    SendMail(GiftBeeSettings("adminEmail"), GiftBeeSettings("adminEmail"), "GiftBee Auth Error", emailMsg);
    return "";
  }

}

// Sends a reward via GiftBee and emails the recipient
// Returns: { status: "success"|"error", uuid?: string, claimUrl?: string }
function GiftBeeGetLink(amount, clientref) {

  // default: not successful unless we explicitly set it
  f('giftbee_success').set(0);

  f('giftbee_start_time').set(Date.now().toString());

  var token = GiftBeeGetAccessToken();
  if (token === "") {
    return { "status": "error", "message": "There was an error. Please try again." };
  }

  var url = GiftBeeSettings("apiBaseUrl") + "/partner/rewards/issue";

  var payload = {
    "ref_id": clientref,
    "notify_recipient_email": false,
    "notify_admin_email": false,
    "value": {
      "amount": parseFloat(amount),
      "currency": GiftBeeSettings("defaultCurrency") || "AUD"
    },
    "personalisation": {
      "from_name": GiftBeeSettings("fromName"),
      "message": ""
    },
    "schedule": {
      "type": "NOW"
    },
    "program": {
      "uuid": GiftBeeSettings("programUuid"),
      "redeemable_country": GiftBeeSettings("redeemableCountry")
    }
  };

  // Include product_uuid only when configured. If omitted/null, API treats it as GiftBee token.
  var configuredProductUuid = GiftBeeSettings("productUuid");
  if (configuredProductUuid !== null && configuredProductUuid !== undefined && configuredProductUuid !== "") {
    payload["product_uuid"] = configuredProductUuid;
  }

  var headers = {
    "Accept": "application/json",
    "Content-Type": "application/json",
    "Authorization": "redacted" + token
  };

  f('giftbee_ref_id').set(payload["ref_id"]);

  // --- bounded retry (NO busy-wait; Forsta-safe) ---
  var maxAttempts = 3;

  var result = "";
  var json = null;
  var attempt = 0;

  for (attempt = 0; attempt < maxAttempts; attempt++) {

    // perform request
    result = Http.PostJson(url, payload, headers);

    // parse JSON safely
    try { json = JSON.parse(result); } catch (e) { json = null; }

    // extract claim_url and then redact it for security
    var claimUrl = null;
    if (json && json["data"] && typeof json["data"]["claim_url"] !== "undefined") {
      claimUrl = json["data"]["claim_url"];
      json["data"]["claim_url"] = null;
    }

    // extract UUID and then redact it for security
    var giftUuid = null;
    if (json && json["data"] && typeof json["data"]["uuid"] !== "undefined") {
      giftUuid = json["data"]["uuid"];
      json["data"]["uuid"] = null;
    }

    // store sanitized response for debugging (claim_url and uuid removed)
    try {
      f('giftbee_result').set(JSON.stringify(json));
    } catch (e2) {
      f('giftbee_result').set(result); // fallback
    }

    // success path
    if (json && typeof json["data"] !== "undefined" && json["data"] != null) {

      // mark success
      f('giftbee_success').set(1);

      f('giftbee_attempts').set(attempt + 1); // 1-based
      f('giftbee_end_time').set(Date.now().toString());

      return {
        "status": "success",
        "message": "the gift URL was created successfully",
        "uuid": giftUuid,
        "claimUrl": claimUrl
      };
    }

    // decide whether to retry based on message contents
    var rawText = (result || "");
    var msgText = "";
    if (json && typeof json["message"] !== "undefined" && json["message"] != null) {
      msgText = String(json["message"]);
    } else if (json && typeof json["error_description"] !== "undefined" && json["error_description"] != null) {
      msgText = String(json["error_description"]);
    }

    var combinedText = (msgText + " " + rawText).toLowerCase();

    // Retry only for wallet-locked in-session (survey-safe).
    // For "too many requests", do NOT hammer the API; fall through to error handler.
    var isWalletLocked = (combinedText.indexOf("this wallet is temporarily locked") >= 0);
    var shouldRetry = isWalletLocked;

    if (shouldRetry && attempt < (maxAttempts - 1)) {
      continue;
    }

    break;
  }
  // --- end retry block ---

  // error handling
  f('giftbee_end_time').set(Date.now().toString());
  f('giftbee_attempts').set(attempt + 1);

  var errMsg = "";
  if (json && typeof json["message"] !== "undefined" && json["message"] != null) {
    errMsg = json["message"];
  } else if (json && typeof json["error_description"] !== "undefined" && json["error_description"] != null) {
    errMsg = json["error_description"];
  } else {
    errMsg = result;
  }

  var emailMsg =
    "GiftBee Get Link Error: " + errMsg +
    "<br>ID: " + clientref;

  SendMail(
    GiftBeeSettings("adminEmail"),
    GiftBeeSettings("adminEmail"),
    "GiftBee Error: " + clientref,
    emailMsg
  );

  return { "status": "error", "message": "There was an error. Please try again." };
}

function GiftBeeSendRewardSMS() {

  //clientref is the unique key in Giftbee to avoid duplicated URLs
  var clientref = CurrentPID() + "_" + GetRespondentValue("respid");

  var valueamount = GiftBeeSettings("valueAmount");

  //Use Giftbee to retrieve the gift URL
  var result = GiftBeeGetLink(valueamount, clientref); 
  var success = f('giftbee_success').get();

  if (success == 1 && result && result["claimUrl"]) {

    f('giftbee_url').set(result["claimUrl"]);
    f('giftbee_gift_uuid').set(result["uuid"]);

