Open.ValidationCode:
if (f('CAWIEmailAddress').toBoolean()) {
    if (!IsEmail(f(CurrentForm()))) {
        showError("Please provide a valid email address.");
    } else {
        // Validity - Request the tempory key
        var APIKey = "redacted"
        var requestString =  "https://api.everest.validity.com/api/2.0/validation/addresses/";
        requestString = requestString + f('CAWIEmailAddress').get()
        var response = Http.Get(requestString,"",{"X-API-Key":APIKey});
        var jsonObj = JSON.parse(response);
        var resultReturn=JSON.parse(JSON.stringify(jsonObj["results"]))
        var resultCategory = JSON.stringify(resultReturn["category"])
        f('EmailReturnValues_category').set(resultCategory.toLowerCase().replace(/""/g, ""))
        f('EmailReturnText').set(JSON.stringify(resultReturn))

        var returnvalueCat=f('EmailReturnValues_category').get()
        if( returnvalueCat.includes("email_domain_invalid")) { 
            showError("Domain for email (AFTER '@') does not exist, please double check it");
        } else if(returnvalueCat.includes("email_address_invalid")) {
            showError("Email address does not exist, please double check your answer");
        } else if(returnvalueCat.includes("email_account_invalid")) {
            showError("Email account does not exist, please double check your answer");
        } else if (returnvalueCat.includes("accept_all")) {
            showError("Email address is possibly invalid, please double check your answer");
        } else if (returnvalueCat.includes("role_address")) {
            showError("Please enter a personal email address rather than a role or shared mailbox");
        } else if (returnvalueCat.includes("disposable")) {
            showError("Temporary or disposable email addresses are not allowed, please enter a different email address");
        }
    }
}

