    } else if (count === 1) {
        //st = set('1', '2', '4');
        st = set('1', '2'); //Only leave 1 message
    } else if (count >= 2) {
        st = set('1', '2');
    }

    return st;
}

function getAnsmMessage() {
    //*(TOPUP_SAMPLE=0 OR 1) AND COMPLETE_STATUS_W4=0 OR 1), MAIN SAMPLE/W4 TOP UP SAMPLE WHO PARTICIPATED IN WAVE 4)
    if (f('topup_sample').any('0','1') && f('COMPLETE_STATUS_W4').any('0','1')) {
        return `Hello, I’m calling about the Generation Survey, which you’ve previously been part of. The survey is being conducted by the Social Research Centre on behalf of the Australian National University and is now open online and by phone. If you complete the survey, you’ll receive a $30 eGift card. We’ll try you again later. Thank you.
        ${StartCatiAudioPlayback("https://apac-1.softdial.cloud/sounds/src/3533VM1.wav",1)}`;
    }
    //*(TOPUP_SAMPLE=2) OR (TOPUP_SAMPLE=1 AND COMPLETE_STATUS_W4=NULL)), W5 TOP UP SAMPLE OR W4 TOP UP SAMPLE WHO DID NOT PARTICIPATE IN WAVE 4)
    if (f('topup_sample').any('2') || (f('topup_sample').any('1') && !f('COMPLETE_STATUS_W4').toBoolean())) {
    return `Hello, I’m calling about the Generation Survey, a national study about what young Australians are doing. The survey is being conducted by the Social Research Centre on behalf of the Australian National University. You previously expressed interest through the Student Experience Survey. The survey is now open and if you complete it you'll receive a one-time $45 eGift card. We'll try you again later. Thank you.
        ${StartCatiAudioPlayback("https://apac-1.softdial.cloud/sounds/src/3533VM2.wav",1)}`;
    }
    //*(TOPUP_SAMPLE=0 AND COMPLETE_STATUS_W4=NULL), MAIN SAMPLE WHO DID NOT PARTICIPATE IN WAVE 4)
    if (f('topup_sample').any('0') && !f('COMPLETE_STATUS_W4').toBoolean()) {
        return `Hello, I’m calling about the Generation Survey, which you’ve previously been part of. The survey is being conducted by the Social Research Centre on behalf of the Australian National University and is now open. While you didn't take part last year, you're still eligible this year. If you complete the survey, you'll receive a one-time $45 eGift card. We'll try you again later. Thank you.
        ${StartCatiAudioPlayback("https://apac-1.softdial.cloud/sounds/src/3533VM3.wav",1)}`;
    }
}

//continue to introduction
if (f('AM_FLAG').any('1') || f('ANSM1').any('2') || f('ANSM2').any('2')) {
