Script.ScriptCode:
function chkTransferDate () {
    // check if not transferred today
    if (!f('TransferDate').toBoolean()) return true;

    var now = new Date();
    var transferDate = f('TransferDate').get();

    if (
        now.getFullYear() === transferDate.getFullYear() &&
        now.getMonth() === transferDate.getMonth() &&
        now.getDate() === transferDate.getDate()
    ) {
        return false;
    }

    return true;
}

//check respondent_state to update AppState
var respState = GetRespondentValue('resp_state');

if (respState != null && respState !== '') {
    f('AppState').set(respState);
}

f('apptyp').set(null);

